// Normalize Google Ads responses into the rules-engine input shape. ₪ = micros / 1e6.
const r2 = (n) => Math.round(n * 100) / 100;
const cRows = ($('Read: Campaign+MTD').first().json.results) || [];
const c = cRows[0] || {};
const campaign = {
  name: c.campaign?.name || 'RSVP Search Campaign',
  status: c.campaign?.status || 'UNKNOWN',
  resourceName: c.campaign?.resourceName || null,
  budgetResourceName: c.campaignBudget?.resourceName || null,
  dailyBudgetILS: r2((Number(c.campaignBudget?.amountMicros) || 0) / 1e6),
  costILS: r2((Number(c.metrics?.costMicros) || 0) / 1e6),
  conversions: Number(c.metrics?.conversions) || 0,
};
const kw90 = {};
for (const r of ($('Read: Keywords 90d').first().json.results) || []) {
  const rn = r.adGroupCriterion?.resourceName;
  if (rn) kw90[rn] = Number(r.metrics?.conversions) || 0;
}
const keywords = (($('Read: Keywords 30d').first().json.results) || []).map((r) => {
  const rn = r.adGroupCriterion?.resourceName;
  return {
    criterionId: rn, // full resource name — used directly in the pause mutation
    text: r.adGroupCriterion?.keyword?.text,
    matchType: r.adGroupCriterion?.keyword?.matchType,
    status: r.adGroupCriterion?.status,
    costILS: r2((Number(r.metrics?.costMicros) || 0) / 1e6),
    conversions: Number(r.metrics?.conversions) || 0,
    clicks: Number(r.metrics?.clicks) || 0,
    conversionsAllTime: kw90[rn] || 0,
  };
});
const searchTerms = (($('Read: Search terms').first().json.results) || []).map((r) => ({
  term: r.searchTermView?.searchTerm,
  clicks: Number(r.metrics?.clicks) || 0,
  costILS: r2((Number(r.metrics?.costMicros) || 0) / 1e6),
  conversions: Number(r.metrics?.conversions) || 0,
  alreadyNegative: false,
}));
const now = new Date();
return [{ json: {
  campaign, keywords, searchTerms,
  monthToDateSpendILS: campaign.costILS,
  dayOfMonth: now.getUTCDate(),
  daysInMonth: new Date(now.getUTCFullYear(), now.getUTCMonth() + 1, 0).getUTCDate(),
} }];

// Deterministic guardrails + candidate actions (mirror of automation/rules-engine.js).
const CONFIG = {
  CAMPAIGN_NAME: 'RSVP Search Campaign',
  MONTHLY_BUDGET_CAP_ILS: 400,
  DAILY_BUDGET_ILS: 13,
  PRICE_ILS: 99,
  LOOKBACK_DAYS: 30,
  KEYWORD_PAUSE_MIN_SPEND_ILS: 60,
  NEGATIVE_MIN_CLICKS: 4,
  NEGATIVE_MIN_SPEND_ILS: 15,
  MAX_ACTIONS_PER_RUN: 8,
};
const { campaign, keywords = [], searchTerms = [], monthToDateSpendILS = 0, dayOfMonth = 1, daysInMonth = 30 } = $input.first().json;
const actions = [];
const notes = [];
const remainingDays = Math.max(1, daysInMonth - dayOfMonth + 1);
const projectedMonth = monthToDateSpendILS + CONFIG.DAILY_BUDGET_ILS * remainingDays;
let budgetStatus = 'ok';
if (monthToDateSpendILS >= CONFIG.MONTHLY_BUDGET_CAP_ILS) {
  actions.push({ type: 'pause_campaign', reason: `MTD ₪${monthToDateSpendILS} reached the ₪${CONFIG.MONTHLY_BUDGET_CAP_ILS} cap` });
  budgetStatus = 'cap_reached';
} else if (projectedMonth > CONFIG.MONTHLY_BUDGET_CAP_ILS) {
  const safeDaily = Math.max(1, Math.floor((CONFIG.MONTHLY_BUDGET_CAP_ILS - monthToDateSpendILS) / remainingDays));
  if (Math.round(campaign.dailyBudgetILS) !== safeDaily) {
    actions.push({ type: 'set_daily_budget', valueILS: safeDaily, reason: `Throttle: projected ₪${Math.round(projectedMonth)} > ₪${CONFIG.MONTHLY_BUDGET_CAP_ILS}` });
  }
  budgetStatus = 'throttling';
} else if (Math.round(campaign.dailyBudgetILS) > CONFIG.DAILY_BUDGET_ILS) {
  actions.push({ type: 'set_daily_budget', valueILS: CONFIG.DAILY_BUDGET_ILS, reason: `Enforce ≤₪${CONFIG.DAILY_BUDGET_ILS}/day (was ₪${Math.round(campaign.dailyBudgetILS)})` });
}
if (budgetStatus !== 'cap_reached' && campaign.status === 'PAUSED') {
  actions.push({ type: 'resume_campaign', reason: `Budget available (₪${monthToDateSpendILS} of ₪${CONFIG.MONTHLY_BUDGET_CAP_ILS} spent this month) — resuming` });
}
const losers = keywords
  .filter((k) => k.status === 'ENABLED' && (k.conversions || 0) === 0 && (k.conversionsAllTime || 0) === 0 && (k.costILS || 0) >= CONFIG.KEYWORD_PAUSE_MIN_SPEND_ILS)
  .sort((a, b) => b.costILS - a.costILS);
for (const k of losers) actions.push({ type: 'pause_keyword', criterionId: k.criterionId, keyword: k.text, matchType: k.matchType, reason: `₪${k.costILS}, 0 conv in ${CONFIG.LOOKBACK_DAYS}d` });
const waste = searchTerms
  .filter((t) => (t.conversions || 0) === 0 && (t.clicks || 0) >= CONFIG.NEGATIVE_MIN_CLICKS && (t.costILS || 0) >= CONFIG.NEGATIVE_MIN_SPEND_ILS && !t.alreadyNegative)
  .sort((a, b) => b.costILS - a.costILS);
for (const t of waste) actions.push({ type: 'add_negative', text: t.term, matchType: 'PHRASE', reason: `₪${t.costILS}, ${t.clicks} clicks, 0 conv` });
const winners = keywords.filter((k) => (k.conversionsAllTime || 0) > 0).map((k) => ({ keyword: k.text, matchType: k.matchType, cpaILS: k.conversions ? Math.round(k.costILS / k.conversions) : null }));
const totalConv = campaign.conversions || 0;
const cpaILS = totalConv ? Math.round((campaign.costILS || 0) / totalConv) : null;
if (budgetStatus === 'cap_reached') notes.push('Budget cap reached — campaign paused until next month.');
if (cpaILS != null && cpaILS < CONFIG.PRICE_ILS) notes.push(`CPA ₪${cpaILS} < ₪${CONFIG.PRICE_ILS} price — profitable.`);
const candidateActions = actions.slice(0, CONFIG.MAX_ACTIONS_PER_RUN);
return [{ json: { budgetStatus, monthToDateSpendILS, projectedMonthILS: Math.round(projectedMonth), cpaILS, profitable: cpaILS != null && cpaILS < CONFIG.PRICE_ILS, winners, candidateActions, droppedActions: Math.max(0, actions.length - candidateActions.length), config: CONFIG, notes } }];

// Build the local-LLM (Ollama) review request. The model may only approve/reject/reorder
// the engine's candidateActions and optionally draft ONE website PR proposal.
const data = $input.first().json;
const SYSTEM = `You are the review layer of an autonomous Google Ads manager for rsvp.kupernet.com, a Hebrew RSVP web app selling one-time event pages for ₪99. A deterministic rules engine computed the ONLY allowed ad changes this run.
HARD LIMITS (violations are dropped by a validator):
1. Ad actions must be a subset of candidateActions — approve/reject/reorder only; never invent actions, change values, or raise budgets.
2. Never approve pausing any keyword listed in winners.
3. Monthly ad spend cap is ₪400; you never propose more spend anywhere.
4. Website changes are PROPOSALS for a human; never touch payment/checkout code (api/paypal-*, create-event, capture flow).
5. Never propose anything that costs money to run.
ACTION TYPES you may see in candidateActions: pause_keyword, add_negative, set_daily_budget, pause_campaign (hit the monthly cap), resume_campaign (a new month started and budget is available again — always approve this one verbatim when present).
GOAL: drive CPA (cpaILS) below ₪99 while keeping conversions. winners shows converting keywords — protect them and lean into their themes (esp. digital/דיגיטלי intent, historically cheapest).
REVIEW: approve candidates unless a reason is clearly wrong (explain rejections); order by impact; if budgetStatus is cap_reached or throttling, approve the budget action verbatim.
WEBSITE PR (optional, max one): only a concrete, safe, content-level improvement (headline matching winning intent, trust element, copy fix). Else websitePR: null.
OUTPUT STRICT JSON ONLY: {"approvedActions":[...subset unchanged...],"rejectedActions":[{"action":{},"why":""}],"websitePR":null|{"title":"","rationale":"","files_hint":"","change_description":""},"summary":"1-3 sentences: CPA, changes, spend vs cap"}`;
return [{ json: { model: 'llama3.1:8b', stream: false, format: 'json', options: { temperature: 0.2 }, messages: [ { role: 'system', content: SYSTEM }, { role: 'user', content: JSON.stringify(data) } ] } }];

// FINAL SAFETY GATE — re-validates the LLM plan against the engine's sanctioned set,
// then builds the exact Google Ads mutation payloads. Nothing outside this passes.
const DRY_RUN = false; // ← flip to true to go back to observe-only mode
const CID = '3674361839'; // ads account, digits only
const API = 'v25'; // bump when Google retires this version — check developers.google.com
const engine = $('Rules Engine').first().json;
const norm = $('Normalize').first().json;
let review = { approvedActions: engine.candidateActions || [], rejectedActions: [], websitePR: null, summary: 'LLM unavailable — engine plan used verbatim.' };
try {
  const raw = $input.first().json || {};
  const content = raw.message?.content ?? raw.choices?.[0]?.message?.content;
  if (content) { const parsed = typeof content === 'string' ? JSON.parse(content) : content; if (parsed && Array.isArray(parsed.approvedActions)) review = parsed; }
} catch (e) { /* fall back to engine plan */ }
const key = (a) => JSON.stringify([a.type, a.criterionId || a.text || '', a.valueILS ?? '']);
const sanctioned = new Map((engine.candidateActions || []).map((a) => [key(a), a]));
const winners = new Set((engine.winners || []).map((w) => w.keyword));
const approved = [];
for (const a of review.approvedActions || []) {
  const s = sanctioned.get(key(a));
  if (!s) continue; // not sanctioned by the engine → dropped
  if (s.type === 'pause_keyword' && winners.has(s.keyword)) continue;
  if (s.type === 'set_daily_budget' && s.valueILS > engine.config.DAILY_BUDGET_ILS && engine.budgetStatus !== 'throttling') continue;
  approved.push(s); // use the ENGINE'S copy, not the LLM's
}
const base = `https://googleads.googleapis.com/${API}/customers/${CID}`;
const mutations = approved.map((a) => {
  if (a.type === 'pause_keyword') return { url: `${base}/adGroupCriteria:mutate`, body: { operations: [{ updateMask: 'status', update: { resourceName: a.criterionId, status: 'PAUSED' } }] }, label: `pause: ${a.keyword}` };
  if (a.type === 'add_negative') return { url: `${base}/campaignCriteria:mutate`, body: { operations: [{ create: { campaign: norm.campaign.resourceName, negative: true, keyword: { text: a.text, matchType: a.matchType || 'PHRASE' } } }] }, label: `negative: ${a.text}` };
  if (a.type === 'set_daily_budget') return { url: `${base}/campaignBudgets:mutate`, body: { operations: [{ updateMask: 'amountMicros', update: { resourceName: norm.campaign.budgetResourceName, amountMicros: String(Math.round(a.valueILS * 1e6)) } }] }, label: `budget: ₪${a.valueILS}/day` };
  if (a.type === 'pause_campaign') return { url: `${base}/campaigns:mutate`, body: { operations: [{ updateMask: 'status', update: { resourceName: norm.campaign.resourceName, status: 'PAUSED' } }] }, label: 'PAUSE CAMPAIGN (monthly cap)' };
  if (a.type === 'resume_campaign') return { url: `${base}/campaigns:mutate`, body: { operations: [{ updateMask: 'status', update: { resourceName: norm.campaign.resourceName, status: 'ENABLED' } }] }, label: 'RESUME CAMPAIGN (budget available)' };
  return null;
}).filter(Boolean);
const websitePR = review.websitePR && review.websitePR.title ? review.websitePR : null;
return [{ json: {
  DRY_RUN,
  summary: review.summary || '(no summary)',
  cpaILS: engine.cpaILS, profitable: engine.profitable,
  budgetStatus: engine.budgetStatus, monthToDateSpendILS: engine.monthToDateSpendILS, projectedMonthILS: engine.projectedMonthILS,
  approvedCount: approved.length, mutations, websitePR,
  rejected: review.rejectedActions || [], engineNotes: engine.notes || [], winners: engine.winners || [],
} }];

// Emit one item per mutation — only when live (DRY_RUN=false). Empty output = nothing runs.
const j = $input.first().json;
if (j.DRY_RUN || !(j.mutations || []).length) return [];
return j.mutations.map((m) => ({ json: m }));

// Emit one item when the reviewer proposed a website change — becomes a GitHub issue
// (a proposal for a human; the agent never deploys website code).
const j = $input.first().json;
if (!j.websitePR) return [];
const pr = j.websitePR;
return [{ json: {
  title: `[ads-agent] ${pr.title}`.slice(0, 120),
  body: `**Rationale:** ${pr.rationale || ''}\n\n**Files:** ${pr.files_hint || 'n/a'}\n\n**Proposed change:**\n${pr.change_description || ''}\n\n---\n_Proposed automatically by the ads agent (CPA ₪${j.cpaILS ?? '—'}, spend ₪${j.monthToDateSpendILS}). Review before implementing — never touches checkout/payment code._`,
} }];
